/bin/bash -c "python - <<'PY'
import inspect
import tilelang.language as T
for name in dir(T):
    if \"reduce\" in name.lower():
        obj = getattr(T, name)
        try:
            sig = inspect.signature(obj)
        except (TypeError, ValueError):
            sig = \"<no-signature>\"
        print(name, sig)
